<script lang="ts">
import {tick,untrack,onMount,onDestroy} from 'svelte';import {LocalSpeechDriver} from './local-speech-driver.js';import {Masthead,Identifier,Header,Footer,SkipLink,MainMenu,Breadcrumb,SideNavigation,InPageNavigation,Pagination,StructuredList,CriticalAlert,Disclosure,Badge,Accordion,Image,Carousel,Table,TextList,Favicon,Link,FAB,RadioGroup,Checkbox,Tag,Switch,StepIndicator,Spinner,HelpPanel,TutorialPanel,ContextualHelp,CoachMark,Tooltip,TTS,Textarea,TextInput,FileUpload,LanguageSwitcher,Resize,AccessibleMedia,VisuallyHidden,RangeSlider,BackButton,BottomSheet,QuantityToggle,Toast,Snackbar,TabBar,Modal} from '@unofficial-krds/svelte';import TutorialExample from './TutorialExample.svelte';
let {componentId,state:s,emit,patch}:{componentId:string;state:Record<string,any>;emit:(name:string,detail:any,next?:Record<string,any>)=>void;patch:(next:Record<string,any>)=>void}=$props();const host=$derived(s.__host??{});const mounted=$derived(host.mounted!==false&&(componentId==='favicon'||!s.__routeRemoved));let result=$state(''),query=$state(''),saved=$state<string[]>([]),speech=$state('idle'),summary=$state(''),locale=$state('ko-KR'),confirmation=$state(false),draft=$state(''),appended=$state(false),receipt=$state(''),configurationError=$state(''),menuOpen=$state(false),route=$state(untrack(()=>s.__host?.history?.at(-1)??'')),persistentText=$state(untrack(()=>s.__host?.persistentResult?.text??s.message?.text??''));let children=$state<any[]>(untrack(()=>(s.__host?.children??[]).map((x:any)=>({...x,checked:x.checked??x.defaultChecked??false}))));const baseline=untrack(()=>children.map(x=>({...x})));let barHeight=$state(0);onMount(()=>{for(const child of baseline){const input=document.getElementById(child.id);if(input instanceof HTMLInputElement)input.defaultChecked=child.checked;}let active=true;let observer:ResizeObserver|undefined;void tick().then(()=>{if(!active)return;const bar=document.querySelector<HTMLElement>('[data-krds-component=tab-bar][data-krds-part=root]');if(bar){const measure=()=>barHeight=Math.ceil(bar.getBoundingClientRect().height);observer=new ResizeObserver(measure);observer.observe(bar);measure();}});return()=>{active=false;observer?.disconnect();};});let confirmResolve:((value:boolean)=>void)|undefined;
let catalogRoot:HTMLDivElement;const menuReturnId=$props.id();function openMenu(){const opener=catalogRoot.querySelector<HTMLButtonElement>('[data-krds-component=tab-bar][data-krds-part=menu-trigger]');if(opener){opener.id=menuReturnId;opener.focus();}menuOpen=true;emit('menuRequest',{});}
const commonForm=untrack(()=>['radio-group','checkbox','switch','textarea','text-input','range-slider','quantity-toggle','file-upload'].includes(componentId));
function change(detail:any){emit('valueChange',detail,{value:detail.value});}function opened(detail:any){emit('openChange',detail,{open:detail.open});}
function eligible(){return children.filter(x=>!x.disabled);}function checked(detail:{checked:boolean}){if(children.length){if(host.acceptChanges!==false)children=children.map(x=>x.disabled?x:{...x,checked:detail.checked});emit('checkedChange',detail,{checked:eligible().every(x=>x.checked),indeterminate:eligible().some(x=>x.checked)&&!eligible().every(x=>x.checked)});}else emit('checkedChange',detail,{checked:detail.checked});}
function childChanged(id:string,value:boolean){children=children.map(x=>x.id===id?{...x,checked:value}:x);patch({checked:eligible().every(x=>x.checked),indeterminate:eligible().some(x=>x.checked)&&!eligible().every(x=>x.checked)});}
function reset(e:Event){if(host.cancelReset){e.preventDefault();return;}setTimeout(()=>{if(e.defaultPrevented)return;children=baseline.map(x=>({...x}));void tick().then(()=>{for(const child of children){const input=document.getElementById(child.id);if(input instanceof HTMLInputElement)input.checked=child.checked;}});if(children.length)patch({checked:eligible().every(x=>x.checked),indeterminate:eligible().some(x=>x.checked)&&!eligible().every(x=>x.checked)});});}
function submit(e:SubmitEvent){e.preventDefault();const data=[...new FormData(e.currentTarget as HTMLFormElement).entries()].map(([key,value])=>[key,value instanceof File?{name:value.name,size:value.size,type:value.type}:value]);receipt=JSON.stringify(data);emit('submit',{entries:data});}
function filesChanged(detail:any){emit('filesChange',detail,{files:detail.value});}function dismiss(detail:any){emit('dismiss',detail,host.acceptDismissal===false?undefined:{message:null});}let speechDriverActive=$state(false),speechDriverLifecycle=$state('idle');const speechDriver=new LocalSpeechDriver(()=>{speechDriverActive=speechDriver.active;speechDriverLifecycle=speechDriver.lifecycle;speech=speechDriver.state;});onDestroy(()=>speechDriver.dispose());function speechRequest(detail:any){emit('request',detail);summary=detail.summary;if(detail.action==='play')speechDriver.play(detail.summary,detail.locale);else if(detail.action==='resume'){if(speechDriver.active)speechDriver.resume();else speechDriver.play(detail.summary,detail.locale);}else if(detail.action==='pause')speechDriver.pause();else speechDriver.stop();patch({state:speech});}function localeRequest(detail:any){emit('localeRequest',detail);document.documentElement.lang=detail.locale;locale=detail.locale;result=s.options.find((o:any)=>o.locale===detail.locale)?.nativeLabel??detail.locale;patch({currentLocale:detail.locale});}function confirm(){confirmation=true;return new Promise<boolean>(resolve=>confirmResolve=resolve);}async function answer(value:boolean){const resolve=confirmResolve;confirmResolve=undefined;resolve?.(value);await tick();confirmation=false;}function back(detail:any){emit('backRequest',detail);route=host.history?.at(-2)??s.fallbackHref??'/local/parent';}function loadMore(){if(host.loadMoreSucceeds===false)return;appended=true;emit('loadMore',{});if(!s.loadMore.pending)patch({loadMore:{...s.loadMore,shown:Math.min(s.loadMore.total,s.loadMore.shown+(host.appendCount??5)),firstNewItemId:'added-item'}});}function sort(detail:any){emit('sortChange',detail,{sort:detail,rows:[...s.rows].sort((a:any,b:any)=>String(a.cells[detail.columnId]).localeCompare(String(b.cells[detail.columnId]))*(detail.direction==='ascending'?1:-1))});}
const shownItems=$derived(s.items?.filter((x:any)=>!query||x.title?.includes(query))??[]);$effect(()=>{if(host.removeTarget)configurationError=String(s.links?.[0]?.targetId??'main-content');});
let resizeValue=$state(untrack(()=>s.value??s.defaultValue??'100'));function resized(detail:any){if(s.value===undefined)resizeValue=detail.value;change(detail);}
$effect(()=>{if(componentId==='tts'&&!mounted)untrack(()=>speechDriver.dispose());});
const resizePercent=$derived(!mounted?100:s.levels?.find((x:any)=>x.id===(s.value??resizeValue))?.percent??Number(s.value??resizeValue));
$effect(()=>{const config=host.testConfiguration;if(!config)return;try{if(componentId==='badge'&&config.tone==='primary')throw new TypeError('Unsupported badge tone');if(componentId==='quantity-toggle'){const v={...s,...config},min=v.min??0,max=v.max??10,step=v.step??1;if(!Number.isInteger((max-min)/step)||(max-min)/step>10)throw new RangeError('Quantity requires at most eleven consistent levels');}configurationError='';}catch(error){configurationError=(error as Error).name+': '+(error as Error).message;}});
</script>
<svelte:head>{#if componentId==='footer'}<style>body{margin:0}</style>{/if}</svelte:head>
<div bind:this={catalogRoot} style="min-height:100vh;display:flex;flex-direction:column" dir={s.__environment?.direction??'ltr'} style:font-size={host.textZoomPercent===200?'200%':undefined}>
