{#if componentId==='header'&&mounted}<SkipLink links={[{id:'main',label:'본문 바로가기',targetId:'main-content'}]}/><Masthead governmentService={false}/><Header {...s as any} search={{label:s.search?.label??'검색',onRequest:()=>{result='검색 열림';emit('searchRequest',{});}}}/>{/if}
{#if componentId==='critical-alert'&&mounted}<CriticalAlert {...s as any}/>{/if}
<main id={!host.removeTarget&&['masthead','skip-link','header'].includes(componentId)?'main-content':undefined} tabindex="-1" style="padding:1rem;min-width:0;padding-bottom:8rem" style:flex={componentId==='footer'?'1':undefined}>
{#if componentId!=='critical-alert'}<h1>독립 KRDS Svelte 예제</h1>{/if}{#if ['accordion','structured-list','coach-mark','tutorial-panel'].includes(componentId)}<h2>신청 안내</h2>{/if}
{#if mounted}
{#if componentId==='identifier'}<p>독립 예제 서비스 정보</p>
{:else if componentId==='main-menu'}<MainMenu {...s as any} onExpandedChange={e=>emit('expandedChange',e,{expandedId:e.id})} onMobileOpenChange={e=>emit('mobileOpenChange',e,{mobileOpen:e.open})} onQueryChange={e=>emit('queryChange',e,{query:e.value})}/>
{:else if componentId==='breadcrumb'}<Breadcrumb {...s as any}/>
{:else if componentId==='side-navigation'}<SideNavigation {...s as any} onExpandedChange={e=>emit('expandedChange',e,{expandedIds:e.ids})}/>
{:else if componentId==='in-page-navigation'}<div style="float:right;width:30%"><InPageNavigation {...s as any} sections={s.sections.filter((x:any)=>x.id!==host.removeSectionId)} onActiveChange={e=>emit('activeChange',e,{activeId:e.id})}/></div>{#each s.sections.filter((x:any)=>x.id!==host.removeSectionId) as item}<section style="min-height:55vh"><div id={item.id} tabindex="-1"><h2>{item.label}</h2><button type="button">{item.label} 조회</button></div><p>이 절의 본문과 예제입니다.</p><button type="button">{item.label} 작업</button></section>{/each}
