{:else if componentId==='structured-list'}<StructuredList {...s as any} items={shownItems} selection={s.selection?{...s.selection,onChange:(e:any)=>emit('selectionChange',e,{selection:{ids:e.ids}})}:undefined}>{#snippet toolbarContent()}<label>공고 검색<input bind:value={query}/></label><button type="button" onclick={()=>query=query?'':'다음'}>필터 적용</button>{#if s.sort}<button type="button" onclick={()=>emit('sortChange',{key:'title',direction:s.sort.direction==='ascending'?'descending':'ascending'},{items:[...s.items].reverse(),sort:{...s.sort,direction:s.sort.direction==='ascending'?'descending':'ascending'}})}>정렬</button>{/if}{/snippet}{#snippet actions(item)}<button type="button" onclick={()=>result=`${item.title} 공유`}>공유</button><button type="button" onclick={()=>saved=saved.includes(item.id)?saved.filter(x=>x!==item.id):[...saved,item.id]}>{saved.includes(item.id)?'저장 취소':'저장'}</button>{/snippet}</StructuredList>
