{:else if componentId==='image'}{#if host.imageLink}<a href={host.imageLink.href} aria-label={host.imageLink.label}><Image {...s as any}/></a>{:else}<Image {...s as any}/>{/if}
{:else if componentId==='carousel'}<Carousel {...s as any} onIndexChange={e=>emit('indexChange',e,{index:e.index})} onPlayingChange={e=>emit('playingChange',e,{playing:e.playing})}>{#snippet slide(item)}<p>{item.content}</p><a href={`/local/slide/${item.id}`}>{item.label} 상세</a>{/snippet}</Carousel>
