{:else if componentId==='quantity-toggle'}<QuantityToggle {...s as any} onValueChange={change}/>{/if}
{#if s.helpId||host.helpText}<p id={s.helpId??'switch-help'}>{host.helpText??'도움말'}</p>{/if}{#if s.errorId}<p id={s.errorId}>{host.errorText??'입력을 확인하세요.'}</p>{/if}<button type="reset">초기화</button><button type="submit">제출</button></form>
{:else if componentId==='tag'}<Tag {...s as any} appliedBarId={host.appliedBarId} onSelectionChange={e=>emit('selectionChange',e,{selectedIds:e.ids})} onRemove={e=>emit('remove',e,{items:s.items.filter((x:any)=>x.id!==e.id)})} onAdd={e=>{emit('add',e);result=s.items.find((x:any)=>x.id===e.id)?.label??e.id;}} onClear={()=>emit('clear',{},{items:[]})}/><div id={s.appliedBarId??host.appliedBarId} tabindex="-1">적용된 필터 {result}</div><p data-krds-host="filtered-results">{s.items.filter((x:any)=>s.selectedIds?.includes(x.id)).map((x:any)=>x.label).join(', ')}</p>
{:else if componentId==='step-indicator'}<StepIndicator {...s as any} onStepRequest={e=>emit('stepRequest',e)}/>{#if host.skipAction}<button type="button" data-krds-host="skip-action" onclick={()=>{emit('stepRequest',{id:s.steps.at(-1).id});route=host.skipDestination;}}>{host.skipAction}</button>{/if}
{:else if componentId==='spinner'}<Spinner {...s as any}/>
{:else if componentId==='help-panel'}<HelpPanel {...s as any} openerId={host.panelOpenerId} hideOpener={host.removePanelOpener} hideTopicTriggers={host.removeTopicTrigger} onOpenChange={opened} onTopicChange={e=>emit('topicChange',e,{selectedTopicId:e.id})}/>
{:else if componentId==='tutorial-panel'||componentId==='coach-mark'}<TutorialExample {componentId} state={s} {emit} {patch}/>
