{:else if componentId==='tooltip'}{#if !host.removeTrigger}<Tooltip {...s as any} onOpenChange={opened}/>{/if}
{:else if componentId==='tts'}<TTS {...s as any} onRequest={speechRequest}/>
{:else if componentId==='language-switcher'}<div onclick={e=>{if(e.button===0&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey)e.preventDefault();}} role="presentation"><LanguageSwitcher {...s as any} onOpenChange={opened} onLocaleRequest={localeRequest}/></div>
{:else if componentId==='resize'}<Resize {...s as any} onOpenChange={opened} onValueChange={resized}/>
{:else if componentId==='accessible-media'}<AccessibleMedia {...s as any} signLanguageSource={undefined}/>{#if s.signLanguageSource}<p data-krds-host="media-content-blocked">수어 영상은 권리와 내용 검토가 끝나지 않아 이 독립 예제에서 제공하지 않습니다.</p>{/if}
{:else if componentId==='visually-hidden'}<VisuallyHidden {...s as any}>{#snippet surrogate()}예제 옵션{/snippet}{#if s.variant==='interactive-overlay'}<input type="checkbox" aria-label="예제 옵션"/>{/if}</VisuallyHidden>
