{:else if componentId==='toast'}{#if host.actionMessage}<button type="button" onclick={()=>{persistentText=host.actionMessage.text;patch({message:host.actionMessage});}}>신청 저장</button>{/if}{#if host.persistentResult}<button type="button" onclick={()=>document.getElementById(host.persistentResult.id)?.focus()}>{host.persistentResult.discoverableLabel??'처리 결과 보기'}</button><p id={host.persistentResult.id} tabindex="-1">{persistentText}</p>{/if}<Toast {...s as any} style={`inset-block-end:${barHeight+16}px`} onDismiss={dismiss}/>
{:else if componentId==='snackbar'}<Snackbar {...s as any} style={`inset-block-end:${barHeight+16}px`} fallbackFocusId={host.fallbackFocusId} onDismiss={dismiss} onAction={e=>{emit('action',e);result='취소 완료';}}/>
{:else if componentId==='tab-bar'}<TabBar {...s as any} menuAction={s.menuAction?{...s.menuAction,onRequest:openMenu}:undefined}/>{/if}{/if}
{#if componentId==='back-button'}<input data-krds-host="dirty-input" aria-label="저장되지 않은 내용" bind:value={draft}/><button type="button" onclick={()=>void confirm().then(allowed=>{if(allowed)route=host.history?.at(-2)??route;})}>브라우저 뒤로가기 모의</button>{/if}
{#if componentId==='resize'}<article data-krds-host="resize-content" style:font-size={`${resizePercent}%`}><h2>확대되는 예제 본문</h2><p>화면 크기 설정에 따라 본문이 줄바꿈됩니다.</p></article>{/if}
