{#if s.loadMore}<span data-krds-host="shown-count">{s.loadMore.shown}</span>{/if}{#if componentId==='bottom-sheet'}<p data-krds-host="committed-selection">{host.selection}</p>{/if}<p data-krds-host="result">{result}</p><p data-krds-host="route">{route}</p><p data-krds-host="configuration-error">{configurationError}</p><pre data-krds-host="upload-receipt">{receipt}</pre><p data-krds-host="speech-driver-active">{String(speechDriverActive)}</p><p data-krds-host="speech-driver-lifecycle">{speechDriverLifecycle}</p><p data-krds-host="speech-state">{speech}</p><p data-krds-host="speech-summary">{summary}</p><p data-krds-host="locale-content">{result||(locale.startsWith('ko')?'한국어 본문':'English local content')}</p>
{#if componentId==='visually-hidden'&&host.visibleControlLabel}<button type="button" aria-describedby={s.id}>{host.visibleControlLabel}</button>{/if}{#if s.descriptionId}<div id={s.descriptionId}>{host.descriptionText??host.description??'복잡한 이미지의 상세 설명'}</div>{/if}{#if appended&&s.loadMore?.firstNewItemId}<section data-krds-host="first-added-result" id={s.loadMore.firstNewItemId} tabindex="-1">새로운 항목</section>{/if}
<Modal open={menuOpen} returnFocusId={menuReturnId} title="전체 메뉴" onOpenChange={e=>menuOpen=e.open}><MainMenu items={[{id:'home',label:'홈',href:'/local/home'},{id:'apply',label:'신청',href:'/local/apply'}]}/></Modal><Modal open={confirmation} title="작성 중인 내용이 있습니다" description="이전 화면으로 이동하면 입력 내용이 사라질 수 있습니다." onOpenChange={()=>answer(false)}><button type="button" onclick={()=>answer(false)}>취소</button><button type="button" onclick={()=>answer(true)}>확인</button></Modal>
</main>{#if componentId==='identifier'&&mounted}<footer data-krds-component="footer" data-krds-part="root" data-krds-state=""><img data-krds-component="footer" data-krds-part="logo" data-krds-state="" src="/local-assets/service-logo.svg" alt="독립 예제 서비스"/><Identifier {...s as any}/></footer>{/if}{#if componentId==='footer'&&mounted}<Footer {...s as any}/>{/if}{#if host.tabBar||host.tabBarPresent||host.tabBarClearance||['fab','toast','snackbar'].includes(componentId)}<TabBar items={host.tabBar?.items??[{id:'home',label:'홈',href:'/local/home',icon:'home'}]} currentId={host.tabBar?.currentId??'home'}/>{/if}</div>
